          maintenance_concurrency: 'Concurrence par processus pour la synchronisation des sources, les traitements groupés et le nettoyage, strictement isolée de la chaîne destinée aux utilisateurs. Minimum 1 ; nécessite un redémarrage du service.',
          shared_concurrency: 'Concurrence élastique par processus partagée entre l\'analyse principale et l\'enrichissement ; le côté qui a du retard l\'emprunte automatiquement. Minimum 1 ; nécessite un redémarrage du service.',
